 // learn from https://p5js.org/examples/arrays-array-objects.html


 var ranges;
 let seed = Math.random() * 192;
 var mySize, margin, grad;
 let str_wei = 0;

 // colors
 let colorsbg = "223240".split("-").map((a) => "#" + a);
 let colors1 = "C16CD9-93D94E-04D9C4-ffffff".split("-").map((a) => "#" + a);
 // let colors2 = "8c75ff-c553d2-2dfd60-2788f5-23054f-f21252-8834f1-c4dd92-184fd3-f9fee2-2E294E-541388-F1E9DA-FFD400-D90368-e9baaa-ffa07a-164555-ffe1d0-acd9e7-4596c7-6d8370-e45240-21d3a4-3303f9-cd2220-173df6-244ca8-a00360-b31016".split("-").map((a) => "#" + a);
 // let colors_cyber = "ee0cf2-352ef2-1df252-f2e41d".split("-").map((a) => "#" + a);
 let color1, color2;
 let colorselet = [];

 let unit_x, unit_y;
 let count;
 let mods = [];
 let stop_count = 0;

 function setup() {
 	// pixelDensity(5);
 	randomSeed(seed);
 	mySize = max(windowWidth, windowHeight);
 	margin = mySize / 100;
 	createCanvas(920, 690);
 	colorselet[0] = "#347355";
 	colorselet[1] = random(colors1);
 	unit_x = width;
 	unit_y = unit_x / 16 * 11;

 	noStroke();
	 let plusNum = random([2,4,3]);
 	let wideCount = width / unit_x;
 	let highCount = height / unit_y + plusNum;
 	count = wideCount * highCount;

 	let index = 0;
 	for (let y = 0; y < highCount; y++) {
 		for (let x = 0; x < wideCount; x++) {
 			mods[index++] = new Module(
 				x * unit_x - unit_x / 100,
 				y * unit_y / (plusNum+1),
 				0,
 				0,
 				random(0.5, 1.0),
 				1 * unit_x
 			);
 		}
 	}
 	let filter1 = new makeFilter();
 	background(colorsbg);
 }

 function draw() {
 	randomSeed(seed);
 	blendMode(ADD);
 	blendMode(SCREEN);

 	for (let i = 0; i < count; i++) {
 		mods[i].update();
 		mods[i].draw();
 		if (stop_count == 1) {
 			blendMode(BLEND);
 			image(overAllTexture, 0, 0);
 			noFill();
 			stroke("#202020");
 			strokeWeight(margin);
 			rectMode(CORNER);
 			//rect(0, 0, width, height);
 			noLoop();
 		}
 	}
 }

 class Module {
 	constructor(xOff, yOff, x, y, speed, unit) {
 		this.xOff = xOff;
 		this.yOff = yOff;
 		this.x = x;
 		this.y = y;
 		this.speed = speed * 2;
 		this.unit = unit;
 		this.xDir = 1;
 		this.yDir = 1 / 16 * 11;
 	}

 	// Custom method for updating the variables
 	update() {
 		this.x = this.x + this.speed * this.xDir;
 		this.y = this.y + this.speed * this.yDir / 10;
 		if (this.x >= this.unit * 2 || this.x <= 0) {
 			this.xDir *= -1;
 			stop_count++;
 			this.x = this.x + 1 * this.xDir;
 			this.y = this.y + 1 * this.yDir;
 		}
 		if (this.y >= this.unit || this.y <= 0) {
 			this.yDir *= -1 / 16 * 11;
 			this.y = this.y + 1 * this.yDir;
 		}
 	}

 	// Custom method for drawing the object
 	draw() {
 		stroke(str(colorselet[1]) + "1a");
 		strokeWeight(0.01);
 		fill(str(random(colorselet)) + "80");

 		//shadow & highlight
 		drawingContext.shadowColor = "#ffffff33";
 		drawingContext.shadowOffsetX = -1;
 		drawingContext.shadowOffsetY = -1;
 		drawingContext.shadowBlur = 0;
 		drawingContext.shadowColor = "#2f2f2f1a";
 		drawingContext.shadowOffsetX = 1;
 		drawingContext.shadowOffsetY = 1;
 		drawingContext.shadowBlur = 0;
 		//shape
 		let y_size = this.unit * noise(random(2), random(5), frameCount * 0.01);
 		let rio = random(0.4, 0.2);
 		let y_plus = y_size * rio;
 		push();
 		translate(this.xOff + this.x, this.yOff + this.y);
 		//gradient
 		grad = drawingContext.createLinearGradient(0, y_plus-y_size / 16 * 11 / 2, 0, y_plus+y_size / 16 * 11 / 2);
 		grad.addColorStop(0, str(colorsbg) + "00");
 		grad.addColorStop(0.5 + random(-0.4, 0.4), colorselet[0]);
 		grad.addColorStop(1, str(colorselet[1]) + "00");
 		drawingContext.fillStyle = grad;
 		rectMode(CENTER);
 		rect(-y_size / 32 * 2, y_plus, (y_size / 16 * 3 - y_plus) * 0.05, y_size / 16 * 11);
 		// rect(0, 0,y_size/16*1, y_size/16*11);
 		pop();
 	}
 }

 function makeFilter() {
 	randomSeed(seed);
 	// noiseのフィルターをつくる
 	colorMode(HSB, 360, 100, 100, 100);
 	drawingContext.shadowColor = color(0, 0, 5, 5);
 	overAllTexture = createGraphics(windowWidth, windowHeight);
 	overAllTexture.loadPixels();
 	for (var i = 0; i < width; i++) {
 		for (var j = 0; j < height; j++) {
 			overAllTexture.set(
 				i,
 				j,
 				color(0, 10, 70, noise(i / 3, j / 3, (i * j) / 50) * random(2, 10))
 			);
 		}
 	}
 	overAllTexture.updatePixels();
 }

 function keyTyped() {
 	if (key === "s" || key === "S") {
 		// image(overAllTexture, 0, 0);
 		// noFill();
 		// stroke("#202020");
 		// strokeWeight(margin);
 		// // rectMode(CORNER);
 		// rect(0, 0, width, height);
 		// noLoop();
 		saveCanvas("0604_NoisePlanet_AURORA_2022", "png");
 	}
 }

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +
    ".jpg");
    lapse = millis();
  }
}

